<nav class="pwa-filter-strip" aria-label="Parcel status"><?php foreach(['active'=>'On the way','ready'=>'Ready','delivered'=>'Delivered','all'=>'All parcels'] as $key=>$label): ?><a href="<?= h(sl_url(['filter'=>$key,'page'=>null])) ?>" <?= $d['filter']===$key?'aria-current="page"':'' ?>><?= h($label) ?></a><?php endforeach; ?></nav>
